     "question": "<style type=\"text/css\">.hsc-q-1digit {\r\n  text-indent:-1.1rem;\r\nmargin-top:0px;\r\n  margin-left:1.1rem;\r\n  margin-bottom:.6rem;\r\n  font-weight: bold;\r\n}\r\n.hsc-q-1digit-noindent {\r\n  margin-left:1.1rem;\r\n  margin-bottom:.6rem;\r\n  font-weight: bold;\r\n}\r\n</style>\r\n<p class=\"hsc-q-1digit\">3&nbsp;&nbsp;&nbsp;Select each item that is an example of quantitative data.&nbsp;(2&nbsp;marks)</p>\r\n\r\n<p class=\"hsc-q-1digit-noindent\">(Multiple items may be selected.)</p>\r\n\r\n<div class=\"item-control\">\r\n<ul style=\"padding-left:1.4em\">\r\n\t<li style=\"list-style-type:none;margin:0px\"><label><input name=\"3\" style=\"margin-right:10px\" type=\"checkbox\" value=\"3A\" />The average cost of a family car</label></li>\r\n\t<li style=\"list-style-type:none;margin:0px\"><label><input name=\"3\" style=\"margin-right:10px\" type=\"checkbox\" value=\"3B\" />User comments on a new product</label></li>\r\n\t<li style=\"list-style-type:none;margin:0px\"><label><input name=\"3\" style=\"margin-right:10px\" type=\"checkbox\" value=\"3C\" />A list of strategies used to solve a problem</label></li>\r\n\t<li style=\"list-style-type:none;margin:0px\"><label><input name=\"3\" style=\"margin-right:10px\" type=\"checkbox\" value=\"3D\" />Gender of the players of a new computer game</label></li>\r\n\t<li style=\"list-style-type:none;margin:0px\"><label><input name=\"3\" style=\"margin-right:10px\" type=\"checkbox\" value=\"3E\" />Number of errors found when testing a new system</label></li>\r\n\t<li style=\"list-style-type:none;margin:0px\"><label><input name=\"3\" style=\"margin-right:10px\" type=\"checkbox\" value=\"3F\" />The percentage of users who responded to a survey</label></li>\r\n\t<li style=\"list-style-type:none;margin:0px\"><label><input name=\"3\" style=\"margin-right:10px\" type=\"checkbox\" value=\"3G\" />A rating (out of 5) given to the quality of customer service</label></li>\r\n\t<li style=\"list-style-type:none;margin:0px\"><label><input name=\"3\" style=\"margin-right:10px\" type=\"checkbox\" value=\"3H\" />The different types of roles required for the development of a system</label></li>\r\n</ul>\r\n</div>\r\n",
