     "question": "<style type=\"text/css\">ul.hsc-q-1dig {\r\n    display: block;\r\n    margin-block-start: 0em;\r\n    margin-block-end: 1em;\r\n    margin-inline-start: 0px;\r\n    margin-inline-end: 0px;\r\n    padding-inline-start:0.8em;\r\n}\r\n\r\nli.hsc-q {\r\n    display: list-item;\r\n    margin-top:0px !important;\r\n    font-weight:bold;\r\n    padding-top:0.2em !important;\r\n    padding-bottom:0.2em !important;\r\n    font-variant-numeric: normal;\r\n    text-align: -webkit-match-parent;\r\n}\r\n.hsc-q-span {\r\n    position:relative;\r\n    left:0.5em;\r\n}\r\nli::marker {\r\n       font-variant-numeric: normal !important;\r\n}\r\n.hsc-html-spreadsheet {\r\nborder-spacing: 0px;\r\nborder-collapse: collapse;\r\nfont-size:0.9rem;\r\ntable-layout: fixed;\r\n}\r\n.hsc-html-spreadsheet tr th {\r\ntext-align:center;\r\nfont-weight:bold;\r\nborder: 1px solid #495054;\r\nbackground-color:#CDD3D6;\r\n  padding:3px 6px; \r\n}\r\n.hsc-html-spreadsheet tr td.outer-top {\r\ntext-align:center;\r\nborder: none;\r\nborder-bottom: 1px solid #495054;\r\n  padding:3px 6px;\r\n}\r\n.hsc-html-spreadsheet tr td.outer-left {\r\ntext-align:center;\r\nfont-weight:bold;\r\nborder: 1px solid #495054;\r\nbackground-color:#CDD3D6;\r\npadding:3px 6px;\r\n}\r\n.hsc-html-spreadsheet tr td.outer-corner {\r\ntext-align:center;\r\nborder: none;\r\nbackground-color:#CDD3D6;\r\npadding:3px 6px;\r\n}\r\n.hsc-html-spreadsheet tr td {\r\ntext-align:center;\r\nborder: 1px solid #495054;\r\n  padding:3px 6px;\r\n}\r\n.optiondefault {\r\n  text-align:center;\r\nbackground-color:#CBEDFD;\r\ncolor:#000;\r\nfont-weight:700;\r\nwidth:4.5rem;\r\n}\r\n.hsc-html-spreadsheet tr td.header {\r\ntext-align:center;\r\nborder: 1px solid #495054;\r\nfont-weight:700;\r\nbackground-color:#CBEDFD;\r\n  padding:3px 6px;\r\n}\r\n.hsc-html-spreadsheet tr td.totals {\r\ntext-align:center;\r\nborder: 1px solid #495054;\r\nborder-bottom: 3px solid #000;\r\n  padding:3px 6px;\r\n}\r\n.item-control input {\r\ntext-align:center;\r\npadding: 3px;\r\nwidth:4rem;\r\n}\r\nselect {\r\nborder: 2px solid #146CFD;\r\n border-radius: 3px;\r\n}\r\n</style>\r\n<ul class=\"hsc-q-1dig\" style=\"list-style-type:'7'\">\r\n\t<li class=\"hsc-q\"><span class=\"hsc-q-span\">On the spreadsheet, choose the correct formula for each of the cells E3, C5, D5 and E5. You need to allow for &lsquo;fill down&rsquo; when appropriate.&nbsp;(4&nbsp;marks)</span></li>\r\n</ul>\r\n\r\n<div class=\"item-control\" style=\"margin-left:1.1rem\">\r\n<table class=\"hsc-html-spreadsheet\">\r\n\t<tbody>\r\n\t\t<tr>\r\n\t\t\t<th class=\"outer-top\" style=\"width:0.8rem\"></th>\r\n\t\t\t<th class=\"outer-top\" style=\"width:12%\">A</th>\r\n\t\t\t<th class=\"outer-top\" style=\"width:8%\">B</th>\r\n\t\t\t<th class=\"outer-top\" style=\"width:25%\">C</th>\r\n\t\t\t<th class=\"outer-top\" style=\"width:25%\">D</th>\r\n\t\t\t<th class=\"outer-top\" style=\"width:25%\">E</th>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">1</td>\r\n\t\t\t<td class=\"header\" colspan=\"5\">Weekly Payroll</td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">2</td>\r\n\t\t\t<td style=\"text-align: left;\"><strong>Base&nbsp;rate&nbsp;($)</strong></td>\r\n\t\t\t<td>25</td>\r\n\t\t\t<td></td>\r\n\t\t\t<td style=\"text-align: left;\"><strong>Standard pay ($)</strong></td>\r\n\t\t\t<td>750</td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">3</td>\r\n\t\t\t<td style=\"text-align: left;\"><strong>Standard hours per week</strong></td>\r\n\t\t\t<td>30</td>\r\n\t\t\t<td></td>\r\n\t\t\t<td style=\"text-align: left;\"><strong>Total weekly pay<br />\r\n\t\t\tfor the company ($)</strong></td>\r\n\t\t\t<td><select class=\"select\" name=\"ECFAM06QA\" style=\"width:100%;text-align-last:center;\"><option disabled=\"disabled\" hidden=\"\" selected=\"selected\" style=\"text-align:center\" value=\"\">E3</option><option>=E5:E8</option><option>=E5+E8</option><option>=SUM(E5:E8)</option><option>=SUM(E5+E8)</option></select></td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">4</td>\r\n\t\t\t<td class=\"header\">Emp ID</td>\r\n\t\t\t<td class=\"header\">Hours worked</td>\r\n\t\t\t<td class=\"header\">Overtime hours</td>\r\n\t\t\t<td class=\"header\">Overtime pay rate</td>\r\n\t\t\t<td class=\"header\">Weekly pay</td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">5</td>\r\n\t\t\t<td>1007</td>\r\n\t\t\t<td>35</td>\r\n\t\t\t<td><select name=\"ECFAM06QB\" style=\"width:100%;text-align-last:center\"><option disabled=\"disabled\" hidden=\"\" selected=\"selected\" style=\"text-align:center\" value=\"\">C5</option><option>=IF(B5&gt;B3, B5-B3, 0)</option><option>=IF(B$5&gt;B$3, B$5-B$3, 0)</option><option>=IF(B5&gt;$B$3, B5-$B$3, 0)</option><option>=IF($B$5&gt;$B$3, $B$5-$B$3, 0)</option></select></td>\r\n\t\t\t<td><select name=\"ECFAM06QC\" style=\"width:100%;text-align-last:center;border 2px solid #146CFD;\"><option disabled=\"disabled\" hidden=\"\" selected=\"selected\" style=\"text-align:center\" value=\"\">D5</option><option>=VLOOKUP(C5,$A$11:$C$14,2)</option><option>=VLOOKUP(C5,$B$11:$C$14,2)</option><option>=VLOOKUP($C$5,$A$11:$C$14,2)</option><option>=VLOOKUP($C$5,$B$11:$C$14,2)</option></select></td>\r\n\t\t\t<td><select name=\"ECFAM06QD\" style=\"width:100%;text-align-last:center;\"><option disabled=\"disabled\" hidden=\"\" selected=\"selected\" style=\"text-align:center\" value=\"\">E5</option><option>=E2+C5*D5</option><option>=$E$2+C5*D5</option><option>=E2+$C$5*$D$5</option><option>=$E$2+$C$5*$D$5</option></select></td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">6</td>\r\n\t\t\t<td>1065</td>\r\n\t\t\t<td>37</td>\r\n\t\t\t<td>7</td>\r\n\t\t\t<td>35</td>\r\n\t\t\t<td>995</td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">7</td>\r\n\t\t\t<td>2089</td>\r\n\t\t\t<td>42</td>\r\n\t\t\t<td>12</td>\r\n\t\t\t<td>40</td>\r\n\t\t\t<td>1230</td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">8</td>\r\n\t\t\t<td>2095</td>\r\n\t\t\t<td>30</td>\r\n\t\t\t<td>0</td>\r\n\t\t\t<td>0</td>\r\n\t\t\t<td>750</td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">9</td>\r\n\t\t\t<td class=\"header\" colspan=\"3\">Overtime Rate Table</td>\r\n\t\t\t<td></td>\r\n\t\t\t<td></td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">10</td>\r\n\t\t\t<td><strong><em>Hours</em></strong></td>\r\n\t\t\t<td><strong><em>Min</em></strong></td>\r\n\t\t\t<td><strong><em>Pay Rate</em></strong></td>\r\n\t\t\t<td></td>\r\n\t\t\t<td></td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">11</td>\r\n\t\t\t<td>0</td>\r\n\t\t\t<td>0</td>\r\n\t\t\t<td>0</td>\r\n\t\t\t<td></td>\r\n\t\t\t<td></td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n  \t<td class=\"outer-left\">12</td>\r\n\t\t\t<td>1-5</td>\r\n\t\t\t<td>1</td>\r\n\t\t\t<td>30</td>\r\n\t\t\t<td></td>\r\n\t\t\t<td></td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n\t\t\t<td class=\"outer-left\">13</td>\r\n\t\t\t<td>6-10</td>\r\n\t\t\t<td>6</td>\r\n\t\t\t<td>35</td>\r\n\t\t\t<td></td>\r\n\t\t\t<td></td>\r\n\t\t</tr>\r\n\t\t<tr>\r\n \t\t<td class=\"outer-left\">14</td>\r\n\t\t\t<td>11-15</td>\r\n\t\t\t<td>11</td>\r\n\t\t\t<td>40</td>\r\n\t\t\t<td></td>\r\n\t\t\t<td></td>\r\n\t\t</tr>\r\n\t</tbody>\r\n</table>\r\n</div>\r\n",
